    <button id="release-button">Release</button>
    <canvas id="canvas" width="400" height="400"></canvas>
    <script>
        class Pendulum {
            constructor(radius, length, canvas, ctx) {
                this.radius = radius;
                this.length = length;
                this.canvas = canvas;
                this.ctx = ctx;
                this.angle = 0;
                this.velocity = 0;
                this.acceleration = 0;
            }

            draw() {
                this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
                this.ctx.beginPath();
                this.ctx.arc(200, 200, this.radius, this.angle - Math.PI/2, this.angle + Math.PI/2);
                this.ctx.stroke();
            }

            update(dt) {
                this.acceleration = -9.8/(this.length/(this.radius+this.radius)); // due to gravity
                this.velocity += this.acceleration * dt;
                this.angle += this.velocity * dt;
                if (this.angle > Math.PI || this.angle < -Math.PI) {
                    this.angle %= Math.PI;
                    this.velocity *= -0.9; // some air resistance
                }
            }
        }

        let pendulum, inputField, releaseButton;
        const canvas = document.getElementById('canvas');
        const ctx = canvas.getContext('2d');

        pendulum = new Pendulum(10, 100, canvas, ctx);
        inputField = document.getElementById('initial-angle');
        releaseButton = document.getElementById('release-button');

        releaseButton.addEventListener('click', () => {
            pendulum.angle = (inputField.value * Math.PI)/180;
            pendulum.velocity = 0;
        });

        function animate() {
            requestAnimationFrame(animate);
            pendulum.update(0.05); // time step
            pendulum.draw();
        }
        animate();
    </script>
